var runGitBlamePorcelain = func(ctx context.Context, repoRoot, path string) (string, error) {
	cmd := exec.CommandContext(ctx, "git", "blame", "--line-porcelain", "--", path)
	cmd.Dir = repoRoot
	var stdout bytes.Buffer
	var stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	err := cmd.Run()
	if err != nil {
		msg := strings.TrimSpace(stderr.String())
		if msg != "" {
			return "", fmt.Errorf("git blame --line-porcelain -- %s: %w: %s", path, err, msg)
		}
		return "", fmt.Errorf("git blame --line-porcelain -- %s: %w", path, err)
	}
	return stdout.String(), nil
}

func loadWhyBlocks(ctx context.Context, path string) ([]whyBlock, error) {
	repoRoot, blamePath, err := resolveWhyBlameTargetPath(ctx, path)
	if err != nil {
		return nil, err
	}

	out, err := runGitBlamePorcelain(ctx, repoRoot, blamePath)
	if err != nil {
		return nil, err
	}
	blocks, err := parseWhyBlamePorcelain(strings.NewReader(out))
	if err != nil {
		return nil, fmt.Errorf("parse git blame output for %s: %w", path, err)
	}
	return blocks, nil
}

func resolveWhyBlameTargetPath(ctx context.Context, userPath string) (string, string, error) {
	repoRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return "", "", err
	}
	repoRoot = normalizeWhyBlamePath(repoRoot)

	absPath, err := resolveWhyBlameAbsolutePath(repoRoot, userPath)
	if err != nil {
		return "", "", err
	}

	relPath := paths.ToRelativePath(absPath, repoRoot)
	if relPath == "" {
		return "", "", fmt.Errorf("path %q is outside the worktree root", userPath)
	}

	return repoRoot, filepath.ToSlash(relPath), nil
}

func resolveWhyBlameAbsolutePath(repoRoot, userPath string) (string, error) {
	if filepath.IsAbs(userPath) {
		return normalizeWhyBlamePath(userPath), nil
	}

	if _, err := os.Stat(userPath); err == nil {
		absPath, err := filepath.Abs(userPath)
		if err != nil {
			return "", err
		}
		return normalizeWhyBlamePath(absPath), nil
	} else if !os.IsNotExist(err) {
		return "", err
	}

	return normalizeWhyBlamePath(filepath.Join(repoRoot, userPath)), nil
}

func normalizeWhyBlamePath(path string) string {
	if resolved, err := filepath.EvalSymlinks(path); err == nil {
		return resolved
	}
	return filepath.Clean(path)
}

func parseWhyBlamePorcelain(r io.Reader) ([]whyBlock, error) {
	scanner := bufio.NewScanner(r)
	scanner.Buffer(make([]byte, 0, 64*1024), 1024*1024)
	var (
		blocks []whyBlock
		cur    *whyBlameHeader
	)

	flush := func() error {
		if cur == nil {
			return nil
		}
		if !cur.ContentSeen {
			return fmt.Errorf("truncated blame record for commit %s at line %d", cur.Hash, cur.EndLine)
		}

		block := whyBlock{
			StartLine: cur.EndLine,
			EndLine:   cur.EndLine,
			Commit:    cur.Meta,
			CodeLines: []string{cur.LineText},
			Detail:    whyDetailCommit,
		}

		if len(blocks) > 0 {
			last := &blocks[len(blocks)-1]
			if last.Commit.Hash == block.Commit.Hash && last.EndLine+1 == block.StartLine {
				last.EndLine = block.EndLine
				last.CodeLines = append(last.CodeLines, block.CodeLines...)
				return nil
			}
		}

		blocks = append(blocks, block)
		return nil
	}

	for scanner.Scan() {
		line := scanner.Text()
		if strings.HasPrefix(line, "\t") {
			if cur == nil {
				return nil, fmt.Errorf("unexpected content line without header: %q", line)
			}
			cur.LineText = strings.TrimPrefix(line, "\t")
			cur.ContentSeen = true
			if err := flush(); err != nil {
				return nil, err
			}
			cur = nil
			continue
		}

		if strings.TrimSpace(line) == "" {
			continue
		}

		fields := strings.Fields(line)
		if len(fields) >= 3 && isHexCommitHash(fields[0]) {
			if err := flush(); err != nil {
				return nil, err
			}

			endLine, err := strconv.Atoi(fields[2])
			if err != nil {
				return nil, fmt.Errorf("invalid blame line number %q: %w", fields[2], err)
			}

			cur = &whyBlameHeader{
				Hash:    fields[0],
				EndLine: endLine,
				Meta: whyCommitInfo{
					Hash:      fields[0],
					ShortHash: shortCommitHash(fields[0]),
				},
			}
			continue
		}

		if cur == nil {
			return nil, fmt.Errorf("unexpected blame metadata without header: %q", line)
		}

		if strings.HasPrefix(line, "author ") {
			cur.Meta.Author = strings.TrimPrefix(line, "author ")
			continue
		}
		if strings.HasPrefix(line, "summary ") {
			cur.Meta.Subject = strings.TrimPrefix(line, "summary ")
			continue
		}
	}

	if err := scanner.Err(); err != nil {
		return nil, err
	}
	if cur != nil {
		if !cur.ContentSeen {
			return nil, fmt.Errorf("truncated blame record for commit %s at line %d", cur.Hash, cur.EndLine)
		}
		if err := flush(); err != nil {
			return nil, err
		}
	}

	return blocks, nil
}

type whyBlameHeader struct {
	Hash        string
	EndLine     int
	Meta        whyCommitInfo
	LineText    string
	ContentSeen bool
}

func shortCommitHash(hash string) string {
	if len(hash) <= 10 {
		return hash
	}
	return hash[:10]
}

func isHexCommitHash(hash string) bool {
	if len(hash) == 0 {
		return false
	}
	for _, r := range hash {
		switch {
		case r >= '0' && r <= '9':
		case r >= 'a' && r <= 'f':
		case r >= 'A' && r <= 'F':
		default:
			return false
		}
	}
	return true
}

