+			continue
+		}
+		seen[block.Commit.Hash] = struct{}{}
+		uniqueHashes = append(uniqueHashes, block.Commit.Hash)
+	}
+
+	resolved := make(map[string]struct {
+		commit whyCommitInfo
+		entire *whyEntireInfo
+	}, len(uniqueHashes))
+	for _, hash := range uniqueHashes {
+		commit, entire, err := resolveWhyCommitMetadata(ctx, hash)
+		if err != nil {
+			return nil, err
+		}
+		resolved[hash] = struct {
+			commit whyCommitInfo
+			entire *whyEntireInfo
+		}{commit: commit, entire: entire}
+	}
+
+	out := make([]whyBlock, len(blocks))
+	copy(out, blocks)
+	for i := range out {
+		block := out[i]
+		if block.Commit.Hash == "" {
+			continue
+		}
+		resolution, ok := resolved[block.Commit.Hash]
+		if !ok {
+			continue
+		}
+		out[i].Commit = resolution.commit
+		if resolution.entire != nil {
+			out[i].Entire = resolution.entire
+		}
+	}
+
+	return out, nil
+}
+
+var resolveWhyCommitMetadata = func(ctx context.Context, hash string) (whyCommitInfo, *whyEntireInfo, error) {
+	info, repo, checkpointID, err := lookupWhyCommitInfo(ctx, hash)
+	if err != nil {
+		return whyCommitInfo{}, nil, err
+	}
+	if checkpointID.IsEmpty() {
+		return info, nil, nil
+	}
+
+	entire, err := lookupWhyCheckpointInfo(ctx, repo, checkpointID, info.Subject)
+	if err != nil {
+		return info, nil, err
+	}
+
+	return info, entire, nil
+}
+
+var lookupWhyCheckpointInfo = func(ctx context.Context, repo *git.Repository, checkpointID id.CheckpointID, commitSubject string) (*whyEntireInfo, error) {
+	if repo == nil {
+		var err error
+		repo, err = openRepository(ctx)
+		if err != nil {
+			return nil, err
+		}
+	}
+
+	v1Store := checkpoint.NewGitStore(repo)
+	v2Store := checkpoint.NewV2GitStore(repo, "origin")
+
+	reader, summary, err := checkpoint.ResolveCommittedReaderForCheckpoint(ctx, checkpointID, v1Store, v2Store, true)
+	if err != nil {
+		return nil, err
+	}
+
+	return loadWhyEntireInfo(ctx, reader, summary, checkpointID, commitSubject)
+}
+
+var loadWhyEntireInfo = loadWhyEntireInfoImpl
+
+func loadWhyEntireInfoImpl(ctx context.Context, reader checkpoint.CommittedReader, summary *checkpoint.CheckpointSummary, checkpointID id.CheckpointID, commitSubject string) (*whyEntireInfo, error) {
+	if summary == nil {
+		return nil, nil
+	}
+
+	sessionIndex := len(summary.Sessions) - 1
+	if sessionIndex < 0 {
+		return &whyEntireInfo{
+			CheckpointID: checkpointID.String(),
+			Summary:      commitSubject,
+			IsFallback:   true,
+		}, nil
+	}
+
+	sessionMetadata, err := readWhySessionMetadata(ctx, reader, checkpointID, sessionIndex)
+	if err != nil {
+		return nil, err
+	}
+	if sessionMetadata == nil {
+		return &whyEntireInfo{
+			CheckpointID: checkpointID.String(),
+			Summary:      commitSubject,
+			IsFallback:   true,
+		}, nil
+	}
+
+	summaryText, isFallback := selectWhySummary(sessionMetadata.Summary, commitSubject)
+	return &whyEntireInfo{
+		CheckpointID: checkpointID.String(),
+		Agent:        string(sessionMetadata.Agent),
+		Summary:      summaryText,
+		IsFallback:   isFallback,
+	}, nil
+}
+
+var readWhySessionMetadata = func(ctx context.Context, reader checkpoint.CommittedReader, checkpointID id.CheckpointID, sessionIndex int) (*checkpoint.CommittedMetadata, error) {
+	if err := ctx.Err(); err != nil {
+		return nil, err
+	}
+
+	switch r := reader.(type) {
+	case interface {
+		ReadSessionMetadata(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*checkpoint.CommittedMetadata, error)
+	}:
+		return r.ReadSessionMetadata(ctx, checkpointID, sessionIndex)
+	case interface {
+		ReadSessionMetadataAndPrompts(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*checkpoint.SessionContent, error)
+	}:
+		content, err := r.ReadSessionMetadataAndPrompts(ctx, checkpointID, sessionIndex)
+		if err != nil {
+			return nil, err
+		}
+		if content == nil {
+			return nil, nil
+		}
+		return &content.Metadata, nil
+	default:
+		return nil, fmt.Errorf("reader does not support metadata-only session reads")
+	}
+}
+
+func selectWhySummary(summary *checkpoint.Summary, commitSubject string) (string, bool) {
+	if summary != nil {
+		if text := strings.TrimSpace(summary.Outcome); text != "" {
+			return text, false
+		}
+		if text := strings.TrimSpace(summary.Intent); text != "" {
+			return text, true
+		}
+	}
+
+	if text := strings.TrimSpace(commitSubject); text != "" {
+		return text, true
+	}
+
+	return "", true
+}
+
+func commitSubject(message string) string {
+	subject, _, found := strings.Cut(message, "\n")
+	if found {
+		return strings.TrimSpace(subject)
+	}
+	return strings.TrimSpace(message)
+}
diff --git a/cmd/entire/cli/why_blame.go b/cmd/entire/cli/why_blame.go
new file mode 100644
index 000000000..79731ee6d
--- /dev/null
+++ b/cmd/entire/cli/why_blame.go
@@ -0,0 +1,180 @@
+package cli
+
+import (
+	"bufio"
+	"bytes"
+	"context"
+	"fmt"
+	"io"
+	"os/exec"
+	"strconv"
+	"strings"
+)
+
+var runGitBlamePorcelain = func(ctx context.Context, path string) (string, error) {
+	cmd := exec.CommandContext(ctx, "git", "blame", "--line-porcelain", "--", path)
+	var stdout bytes.Buffer
+	var stderr bytes.Buffer
+	cmd.Stdout = &stdout
+	cmd.Stderr = &stderr
+
+	err := cmd.Run()
+	if err != nil {
+		msg := strings.TrimSpace(stderr.String())
+		if msg != "" {
+			return "", fmt.Errorf("git blame --line-porcelain -- %s: %w: %s", path, err, msg)
+		}
+		return "", fmt.Errorf("git blame --line-porcelain -- %s: %w", path, err)
+	}
+	return stdout.String(), nil
+}
+
+func loadWhyBlocks(ctx context.Context, path string) ([]whyBlock, error) {
+	out, err := runGitBlamePorcelain(ctx, path)
+	if err != nil {
+		return nil, err
+	}
+	blocks, err := parseWhyBlamePorcelain(strings.NewReader(out))
+	if err != nil {
+		return nil, fmt.Errorf("parse git blame output for %s: %w", path, err)
+	}
+	return blocks, nil
+}
+
+func parseWhyBlamePorcelain(r io.Reader) ([]whyBlock, error) {
+	scanner := bufio.NewScanner(r)
+	scanner.Buffer(make([]byte, 0, 64*1024), 1024*1024)
+	var (
+		blocks []whyBlock
+		cur    *whyBlameHeader
+	)
+
+	flush := func() error {
+		if cur == nil {
+			return nil
+		}
+		if !cur.ContentSeen {
+			return fmt.Errorf("truncated blame record for commit %s at line %d", cur.Hash, cur.EndLine)
+		}
+
+		block := whyBlock{
+			StartLine: cur.EndLine,
+			EndLine:   cur.EndLine,
+			Commit:    cur.Meta,
+			CodeLines: []string{cur.LineText},
+			Detail:    whyDetailCommit,
+		}
+
+		if len(blocks) > 0 {
+			last := &blocks[len(blocks)-1]
+			if last.Commit.Hash == block.Commit.Hash && last.EndLine+1 == block.StartLine {
+				last.EndLine = block.EndLine
+				last.CodeLines = append(last.CodeLines, block.CodeLines...)
+				return nil
+			}
+		}
+
+		blocks = append(blocks, block)
+		return nil
+	}
+
+	for scanner.Scan() {
+		line := scanner.Text()
+		if strings.HasPrefix(line, "\t") {
+			if cur == nil {
+				return nil, fmt.Errorf("unexpected content line without header: %q", line)
+			}
+			cur.LineText = strings.TrimPrefix(line, "\t")
+			cur.ContentSeen = true
+			if err := flush(); err != nil {
+				return nil, err
+			}
+			cur = nil
+			continue
+		}
+
+		if strings.TrimSpace(line) == "" {
+			continue
+		}
+
+		fields := strings.Fields(line)
+		if len(fields) >= 3 && isHexCommitHash(fields[0]) {
+			if err := flush(); err != nil {
+				return nil, err
+			}
+
+			endLine, err := strconv.Atoi(fields[2])
+			if err != nil {
+				return nil, fmt.Errorf("invalid blame line number %q: %w", fields[2], err)
+			}
+
+			cur = &whyBlameHeader{
+				Hash:    fields[0],
+				EndLine: endLine,
+				Meta: whyCommitInfo{
+					Hash:      fields[0],
+					ShortHash: shortCommitHash(fields[0]),
+				},
+			}
+			continue
+		}
+
+		if cur == nil {
+			return nil, fmt.Errorf("unexpected blame metadata without header: %q", line)
+		}
+
+		if strings.HasPrefix(line, "author ") {
+			cur.Meta.Author = strings.TrimPrefix(line, "author ")
+			continue
+		}
+		if strings.HasPrefix(line, "summary ") {
+			cur.Meta.Subject = strings.TrimPrefix(line, "summary ")
+			continue
+		}
+	}
+
+	if err := scanner.Err(); err != nil {
+		return nil, err
+	}
+	if cur != nil {
+		if !cur.ContentSeen {
+			return nil, fmt.Errorf("truncated blame record for commit %s at line %d", cur.Hash, cur.EndLine)
+		}
+		if err := flush(); err != nil {
+			return nil, err
+		}
+	}
+
+	return blocks, nil
+}
+
+type whyBlameHeader struct {
+	Hash        string
+	EndLine     int
+	Meta        whyCommitInfo
+	LineText    string
+	ContentSeen bool
+}
+
+func shortCommitHash(hash string) string {
+	if len(hash) <= 10 {
+		return hash
+	}
+	return hash[:10]
+}
+
+func isHexCommitHash(hash string) bool {
+	if len(hash) == 0 {
+		return false
+	}
+	for _, r := range hash {
+		switch {
+		case r >= '0' && r <= '9':
+		case r >= 'a' && r <= 'f':
+		case r >= 'A' && r <= 'F':
+		default:
+			return false
+		}
+	}
+	return true
+}
