+func TestWhyBlock_PreservesEntireMetadata(t *testing.T) {
+	t.Parallel()
+
+	block := whyBlock{
+		StartLine: 17,
+		EndLine:   28,
+		Commit: whyCommitInfo{
+			Hash:      "b550507521abcdef",
+			ShortHash: "b550507521",
+			Author:    "Victor Gutierrez",
+			Subject:   "Handle interrupt signals",
+		},
+		Entire: &whyEntireInfo{
+			CheckpointID: "a3b2c4d5e6f7",
+			Agent:        "Claude Code",
+			Summary:      "Add cross-platform signal handling for CLI shutdown.",
+			IsFallback:   false,
+		},
+		Detail: whyDetailCommit,
+	}
+
+	if got, want := block.RangeText(), "17-28"; got != want {
+		t.Fatalf("range text = %q, want %q", got, want)
+	}
+	if block.Entire == nil {
+		t.Fatal("expected Entire metadata")
+	}
+	if block.Entire.CheckpointID != "a3b2c4d5e6f7" {
